// A JSON string as its code points, each packed into 4 bytes, so one code point = 4 chars.
string parseString() {
    string s;
    auto put = [&](uint32_t cp) {
        for (int shift = 24; shift >= 0; shift -= 8) s += (char)((cp >> shift) & 0xFF);
    };
    p++;  // opening quote
    while (in[p] != '"') {
        unsigned char c = in[p];
        if (c == '\\') {
            char e = in[p + 1];
            p += 2;
            if (e == 'b') put(8);
            else if (e == 'f') put(12);
            else if (e == 'n') put(10);
            else if (e == 'r') put(13);
            else if (e == 't') put(9);
            else if (e == 'u') {
                uint32_t u = hex4();
                if (u >= 0xD800 && u <= 0xDBFF && in.compare(p, 2, "\\u") == 0) {
                    size_t save = p;
                    p += 2;
                    uint32_t low = hex4();
                    if (low >= 0xDC00 && low <= 0xDFFF) u = 0x10000 + ((u - 0xD800) << 10) + (low - 0xDC00);
                    else p = save;
                }
                put(u);
            } else put((unsigned char)e);
        } else {
            int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
            uint32_t cp = extra == 0 ? c : extra == 1 ? c & 0x1F : extra == 2 ? c & 0x0F : c & 0x07;
            for (int i = 1; i <= extra; i++) cp = (cp << 6) | (in[p + i] & 0x3F);
            put(cp);
            p += extra + 1;
        }
    }
    p++;
    return s;
}

