import java.io.*;
import java.util.*;

public class Main {
    static byte[] in;
    static int p = 0;

    static int hex4() {
        int v = 0;
        for (int i = 0; i < 4; i++) v = v * 16 + Character.digit(in[p++], 16);
        return v;
    }

    // A JSON string as its code points, each packed into two chars, so one code point = 2 chars.
    static String parseString() {
        StringBuilder s = new StringBuilder();
        p++; // opening quote
        while (in[p] != '"') {
            int c = in[p] & 0xFF, cp;
            if (c == '\\') {
                int e = in[p + 1];
                p += 2;
                if (e == 'b') cp = 8;
                else if (e == 'f') cp = 12;
                else if (e == 'n') cp = 10;
                else if (e == 'r') cp = 13;
                else if (e == 't') cp = 9;
                else if (e == 'u') {
                    cp = hex4();
                    if (cp >= 0xD800 && cp <= 0xDBFF && p + 1 < in.length && in[p] == '\\' && in[p + 1] == 'u') {
                        int save = p;
                        p += 2;
                        int low = hex4();
                        if (low >= 0xDC00 && low <= 0xDFFF) cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                        else p = save;
                    }
                } else cp = e;
            } else {
                int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
                cp = extra == 0 ? c : extra == 1 ? c & 0x1F : extra == 2 ? c & 0x0F : c & 0x07;
                for (int i = 1; i <= extra; i++) cp = (cp << 6) | (in[p + i] & 0x3F);
                p += extra + 1;
            }
            s.append((char) (cp >>> 16)).append((char) (cp & 0xFFFF));
        }
        p++;
        return s.toString();
    }

    public static void main(String[] args) throws IOException {
        in = System.in.readAllBytes();
        // The input is [begin, end, [words...]]: its strings in order are begin, end, then the words.
        List<String> strs = new ArrayList<>();
        while (p < in.length) {
            if (in[p] == '"') strs.add(parseString());
            else p++;
        }
        String begin = strs.get(0), end = strs.get(1);
        List<String> list = strs.subList(2, strs.size());
        if (begin.equals(end)) {
            System.out.println(0);
            return;
        }
        if (!list.contains(end) || begin.length() != end.length()) {
            System.out.println(-1);
            return;
        }
        Set<String> unique = new LinkedHashSet<>();
        for (String w : list)
            if (w.length() == begin.length()) unique.add(w);
        unique.add(begin);
        List<String> words = new ArrayList<>(unique);
        Map<String, Integer> index = new HashMap<>();
        for (int i = 0; i < words.size(); i++) index.put(words.get(i), i);
        int L = begin.length() / 2;
        // Bucket key: (deleted position, the rest); one bucket = words one replacement apart there.
        Map<String, List<Integer>> groups = new HashMap<>();
        for (int id = 0; id < words.size(); id++)
            for (int i = 0; i < L; i++) groups.computeIfAbsent(key(words.get(id), i), k -> new ArrayList<>()).add(id);
        boolean[] seen = new boolean[words.size()];
        int start = index.get(begin);
        seen[start] = true;
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[] {start, 0});
        while (!q.isEmpty()) {
            int[] top = q.poll();
            for (int i = 0; i < L; i++) {
                // Expand each bucket once: everything in it is reached at this distance.
                List<Integer> members = groups.remove(key(words.get(top[0]), i));
                if (members == null) continue;
                for (int other : members) {
                    if (words.get(other).equals(end)) {
                        System.out.println(top[1] + 1);
                        return;
                    }
                    if (!seen[other]) {
                        seen[other] = true;
                        q.add(new int[] {other, top[1] + 1});
                    }
                }
            }
        }
        System.out.println(-1);
    }

    static String key(String w, int i) {
        return (char) i + w.substring(0, 2 * i) + w.substring(2 * i + 2);
    }
}

