var in []byte
var p int

func hex4() uint32 {
	v := uint32(0)
	for i := 0; i < 4; i++ {
		c := in[p]
		p++
		switch {
		case c >= '0' && c <= '9':
			v = v*16 + uint32(c-'0')
		case c >= 'a' && c <= 'f':
			v = v*16 + uint32(c-'a'+10)
		default:
			v = v*16 + uint32(c-'A'+10)
		}
	}
	return v
}

// parseString returns a JSON string as its code points, each packed into 4 bytes.
func parseString() string {
	var s strings.Builder
	put := func(cp uint32) {
		s.Write([]byte{byte(cp >> 24), byte(cp >> 16), byte(cp >> 8), byte(cp)})
	}
	p++ // opening quote
	for in[p] != '"' {
		c := in[p]
		if c == '\\' {
			e := in[p+1]
			p += 2
			switch e {
			case 'b':
				put(8)
			case 'f':
				put(12)
			case 'n':
				put(10)
			case 'r':
				put(13)
			case 't':
				put(9)
			case 'u':
				u := hex4()
				if u >= 0xD800 && u <= 0xDBFF && p+1 < len(in) && in[p] == '\\' && in[p+1] == 'u' {
					save := p
					p += 2
					low := hex4()
					if low >= 0xDC00 && low <= 0xDFFF {
						u = 0x10000 + (u-0xD800)<<10 + (low - 0xDC00)
					} else {
						p = save
					}
				}
				put(u)
			default:
				put(uint32(e))
			}
			continue
		}
		extra, cp := 0, uint32(c)
		switch {
		case c >= 0xF0:
			extra, cp = 3, uint32(c&0x07)
		case c >= 0xE0:
			extra, cp = 2, uint32(c&0x0F)
		case c >= 0x80:
			extra, cp = 1, uint32(c&0x1F)
		}
		for i := 1; i <= extra; i++ {
			cp = cp<<6 | uint32(in[p+i]&0x3F)
		}
		put(cp)
		p += extra + 1
	}
	p++
	return s.String()
}

func main() {
	in, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	// The input is [begin, end, [words...]]: its strings in order are begin, end, then the words.
	strs := []string{}
