		if _, ok := index[w]; !ok && len(w) == len(begin) {
			index[w] = len(words)
			words = append(words, w)
		}
	}
	L := len(begin) / 4
	type bucket struct {
		pos  int
		rest string
	}
	// One bucket = words that differ only at the deleted position.
	key := func(w string, i int) bucket { return bucket{i, w[:4*i] + w[4*i+4:]} }
	groups := map[bucket][]int{}
