	queue := []item{{start, 0}}
	for head := 0; head < len(queue); head++ {
		cur := queue[head]
		for i := 0; i < L; i++ {
			// Expand each bucket once: everything in it is reached at this distance.
			k := key(words[cur.id], i)
			members, ok := groups[k]
			if !ok {
				continue
			}
			delete(groups, k)
			for _, other := range members {
				if words[other] == end {
					fmt.Println(cur.d + 1)
					return
				}
				if !seen[other] {
					seen[other] = true
					queue = append(queue, item{other, cur.d + 1})
				}
			}
		}
	}
	fmt.Println(-1)
}
